/* ★ 顺序：知识点命中在前、100Days 主题索引在后。
   这是个讲义阅读器 —— 搜"列表"十有八九是想跳到正文；主题索引是补充入口。
   （别用 CSS order 反转：DOM 顺序和视觉顺序不一致会破坏 Tab 顺序。） */
var parts = [], topicParts = [];
if (topics.length){
  var idxN = Object.keys(topicIndexMap() || {}).length;
  topicParts.push('<div class="secHead">100Days 主题索引（共 ' + escapeHtml(idxN) + ' 个主题，命中 ' +
    escapeHtml(topics.length) + ' 个）</div>');
  topics.forEach(function(t){
    var links = t.days.map(function(d){
      var info = dayInfo(d);
      var label = "Day" + escapeHtml(d) + (info && info.title ? " " + escapeHtml(info.title) : "");
      return '<button class="chip" data-act="dayfile" data-day="' + attr(d) + '">📖 ' +
        escapeHtml(label) + "</button>";
    }).join("");
    topicParts.push('<div class="topicRow"><span class="topicName">' + escapeHtml(t.topic) + "</span>" +
      '<span class="topicDays">' + (links || '<span class="loading">（索引里没写 Day）</span>') + "</span></div>");
  });
}
if (res.length) parts.push('<div class="secHead">知识点（' + escapeHtml(res.length) + " 条）</div>");
